var msg = input || context.message || context.text || '';
var cats = context.availableCategories || [];
var catList = cats.map(function(c){ return c.id + ': ' + c.name + ' (' + c.network + ')'; }).join('\n');
var msgJson = JSON.stringify(msg).slice(1, -1);

// ── Conversation history (forwarded by content2 dashboard) ──────────────
// Rendered into a single plain string — messagesTemplate must never receive objects.
var hist = Array.isArray(context.history) ? context.history : [];
var histLines = hist.map(function(m){
  var role = (m && m.role === 'assistant') ? 'assistant' : 'user';
  var c = String((m && m.content) || '').replace(/\s+/g, ' ').trim().slice(0, 500);
  return '[' + role + ']: ' + c;
});
var historyText = histLines.join('\n');
var dispatchInput = (historyText ? ('ІСТОРІЯ ДІАЛОГУ (старіші зверху):\n' + historyText + '\n\n') : '')
  + 'ПОТОЧНЕ ПОВІДОМЛЕННЯ КОРИСТУВАЧА: ' + msg;
var dispatchInputJson = JSON.stringify(dispatchInput).slice(1, -1);

// Static tools list — fallback (overridden by dynamic fetch from /api/tools/for-bot)
var availableToolsText = [
  '- content-ai-bg: AI-фон (FLUX schnell) + накладений текст. Для: інфопости, цитати, анонси, кейси. | Параметри: imagePrompt (text, required), palette (select [DARK_CINEMATIC|MINIMAL_WHITE|ENERGY_ORANGE|TRUST_BLUE|PREMIUM_PURPLE])',
  '- content-ai-bg-pro: AI-фон 2K (FLUX Pro). Для преміум контенту. | Параметри: imagePrompt (text, required), palette (select [DARK_CINEMATIC|MINIMAL_WHITE|ENERGY_ORANGE|TRUST_BLUE|PREMIUM_PURPLE])',
  '- content-ideogram: Ideogram V3 — текст ВСЕРЕДИНІ картинки. Для: меми, афіші, написи. | Параметри: imagePrompt (text, required), style (select [realistic|design|illustration|3d])',
  '- content-recraft: Recraft V4 — брендовий дизайн. | Параметри: imagePrompt (text, required), style (select [realistic_image|digital_illustration|vector_illustration|icon])',
  '- content-stories-ai-bg: Stories 9:16 (Vertex AI Imagen 4) + накладаємо текст. Для: Instagram Stories. | Параметри: imagePrompt (text, required), title (text, required, max 7 слів), subtitle (text, optional)',
  '- content-photo-text: Сторіз 9:16 — текст поверх РЕАЛЬНОГО фото автора з бібліотеки (пілюля-тег + CTA). Для провокацій/CTA/живих сцен/особистого. | Параметри: template (multi-plate), tag (text), title (text, required), subtitle (text), cta (text)',
  '- content-carousel: Карусель з безшовним фоном. | Параметри: slides (number, required), imagePrompt (text, required), palette (select [DARK_CINEMATIC|MINIMAL_WHITE|ENERGY_ORANGE|TRUST_BLUE|PREMIUM_PURPLE])',
  '- content-image-template: Рендер за шаблоном. | Параметри: templateId (text, required), fields (json, required)',
  '- content-video-broll: AI B-roll відео (Kling). Для: Reels, TikTok. | Параметри: videoPrompt (text, required), duration (number)'
].join('\n');

return {
  userMessage: msg,
  userMessageJson: msgJson,
  lastUserInput: msg,
  historyText: historyText,
  dispatchInputJson: dispatchInputJson,
  webCallbackUrl: null,
  webSessionId: context.sessionId || context.webSessionId || '',
  importUrl: context.importUrl || 'https://content2.fineko.space/api/posts/bulk-import?token=fnk_wh_2026_x9mK4pLqR7vNsT1eYcJdBuAw',
  saveKnowledgeUrl: context.saveKnowledgeUrl || null,
  phase: 'dispatch',
  stRules: context.stRules || '',
  projectId: context.projectId || keys.CONTENT2_PROJECT_ID,
  today: new Date(Date.now() + 3*3600*1000).toISOString().slice(0,10),
  todayISO: new Date(Date.now() + 3*3600*1000).toISOString().slice(0,10),
  availableCategories: cats,
  categoriesText: catList || 'категорії не завантажено',
  availableToolsText: availableToolsText,
};

var raw = context.intentRaw;
var parsed = typeof raw === 'object' ? raw : {};
try { if (typeof raw === 'string') parsed = JSON.parse(raw); } catch(e) {}

var intent = parsed.intent || 'dialog';
var tasks = Array.isArray(parsed.tasks) ? parsed.tasks : [];
var needsTheme = parsed.needs_theme === true;
var originalMsg = parsed.originalMessage || context.userMessage || '';
var historyText = context.historyText || '';

function parseTodaySafe(s){
  if(!s) return new Date();
  if(/^\d{4}-\d{2}-\d{2}$/.test(s)) return new Date(s);
  var m=s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{2,4})$/);
  if(m){var y=parseInt(m[3]);if(y<100)y+=2000;return new Date(y,parseInt(m[2])-1,parseInt(m[1]));}
  return new Date();
}
var baseToday = parseTodaySafe(context.todayISO || context.today);
var todayISO = baseToday.toISOString().slice(0,10);

var UK_MONTHS={'січня':0,'лютого':1,'березня':2,'квітня':3,'травня':4,'червня':5,'липня':6,'серпня':7,'вересня':8,'жовтня':9,'листопада':10,'грудня':11};
function resolveDate(dstr){
  if(!dstr) return null;
  var s=String(dstr).toLowerCase().trim();
  var m=s.match(/(\d{1,2})\.(\d{1,2})(?:\.(\d{2,4}))?/);
  if(m){var y=m[3]?parseInt(m[3]):baseToday.getFullYear();if(y<100)y+=2000;return new Date(y,parseInt(m[2])-1,parseInt(m[1])).toISOString().slice(0,10);}
  for(var mn in UK_MONTHS){ if(s.indexOf(mn)>=0){ var mm=s.match(new RegExp('(\\d{1,2})\\s*'+mn)); if(mm){ return new Date(baseToday.getFullYear(),UK_MONTHS[mn],parseInt(mm[1])).toISOString().slice(0,10);} } }
  var off=null;
  if(/після\s*завтра|післязавтра|послязавтра/.test(s)) off=2;
  else if(/завтра/.test(s)) off=1;
  else if(/наступн.*тиж/.test(s)) off=7;
  else if(/сьогодн/.test(s)) off=0;
  if(off!==null){ var d=new Date(baseToday.getTime()); d.setDate(d.getDate()+off); return d.toISOString().slice(0,10); }
  return null;
}

// How many DAYS a date phrase spans. >1 => spread posts evenly across the range.
function rangeSpan(dstr){
  var s=String(dstr||'').toLowerCase().trim();
  if(!s) return 1;
  if(/сьогодн|післязавтра|послязавтра|після\s*завтра|завтра/.test(s)) return 1;
  var m=s.match(/(\d+)\s*тижн/);            // "2 тижні", "3 тижнів"
  if(m) return parseInt(m[1],10)*7;
  if(/два\s*тижн|двох\s*тижн|пару\s*тижн/.test(s)) return 14;
  m=s.match(/(\d+)\s*дн/);                  // "10 днів", "5 дн"
  if(m) return parseInt(m[1],10);
  if(/місяц|місяч/.test(s)) return 30;
  if(/тиждень|тижня|наступн.*тиж|на\s*тиж/.test(s)) return 7;
  return 1;
}

var FMT={instagram_stories:'Instagram Сторіз',instagram_post:'Instagram пост',instagram_carousel:'Instagram карусель',instagram_reels:'Instagram Reels',threads_single:'Threads',threads_chain:'Threads ланцюжок',linkedin_post:'LinkedIn',telegram_post:'Telegram'};

var total=0, lines=[], confirmLines=[], resolvedTasks=[], themeFound=null;
for(var i=0;i<tasks.length;i++){
  var t=tasks[i]||{};
  var fmt=t.format||'instagram_post';
  var cnt=parseInt(t.count,10)||1;
  var topic=t.topic||null;
  if(topic && !themeFound) themeFound=topic;
  var dISO=resolveDate(t.date) || todayISO;
  var label=FMT[fmt]||fmt;
  var isSeq=(fmt==='instagram_stories' && cnt>1);
  var isCar=(fmt==='instagram_carousel');
  var seqNote = isSeq ? (' — ОДНА зв\'язна серія сторіз: послідовний наратив (проблема→рішення→результат). ВІЗУАЛ ОДНАКОВИЙ для всієї серії: та сама палітра, той самий фон/стиль/колорит у funnel_params.imagePrompt (однаковий початок imagePrompt у всіх, змінюється лише акцент). У полі content — короткий підпис реченням, НЕ номер серії') : (isCar ? (' — слайди однією зв\'язною історією; спільний стиль і ОДНА палітра, безшовний візуал') : '');

  // Spread a multi-count task across consecutive days when the date phrase is a
  // range ("2 тижні", "10 днів", "тиждень"). Series/carousel stay on one date.
  var span=rangeSpan(t.date);
  if(span>1 && cnt>1 && !isSeq && !isCar){
    var startD=new Date(baseToday.getTime());          // ranges anchor at today
    var perDay=Math.ceil(cnt/span);
    var buckets={}, order2=[];
    for(var k=0;k<cnt;k++){
      var dayIdx=Math.min(span-1, Math.floor(k/perDay));
      var dd=new Date(startD.getTime()); dd.setDate(dd.getDate()+dayIdx);
      var dk=dd.toISOString().slice(0,10);
      if(buckets[dk]===undefined){buckets[dk]=0; order2.push(dk);}
      buckets[dk]++;
    }
    for(var oi=0;oi<order2.length;oi++){
      var dk2=order2[oi], c2=buckets[dk2];
      total+=c2;
      lines.push(c2+'× '+fmt+' (platform='+(t.platform||'')+'), дата '+dk2+(topic?(', тема: '+topic):''));
      confirmLines.push('• '+c2+'× '+label+' на '+dk2+(topic?(' — тема: '+topic):''));
      resolvedTasks.push({format:fmt,platform:t.platform||'',count:c2,date:dk2,topic:topic,sequential:false});
    }
  } else {
    total+=cnt;
    lines.push(cnt+'× '+fmt+' (platform='+(t.platform||'')+'), дата '+dISO+(topic?(', тема: '+topic):'')+seqNote);
    confirmLines.push('• '+cnt+'× '+label+' на '+dISO+(topic?(' — тема: '+topic):''));
    resolvedTasks.push({format:fmt,platform:t.platform||'',count:cnt,date:dISO,topic:topic,sequential:isSeq});
  }
}
if(total===0) total=1;

var breakdownInline = lines.join(' // ');
var taskBreakdownText = lines.join('\n');

// ── Async month-chunking ─────────────────────────────────────────────────
// A big plan (e.g. "місяць, 5/день") would need ~30 Sonnet calls in one HTTP
// request → timeout, and nothing imported. Instead we process ONE small chunk
// per request and self-continue for the rest (node "Plan self-continue" at the
// end fires the next chunk, carrying the remaining tasks). Repeats across chunks
// are prevented by the topic 14-day cooldown; cohesion by a carried arc line.
var CHUNK_MAX = 10; // posts generated per HTTP request (safe ~1-2 batches)

// Continuation request: use the pre-sliced tasks handed to us, skip dispatcher output.
var __ovr = null;
try { if (context._resolvedTasksOverride) __ovr = JSON.parse(context._resolvedTasksOverride); } catch(e) {}
if (Array.isArray(__ovr) && __ovr.length) {
  resolvedTasks = __ovr;
  intent = 'create'; needsTheme = false;
  total = 0; lines = []; confirmLines = [];
  resolvedTasks.forEach(function(r){
    total += (parseInt(r.count,10)||1);
    lines.push(r.count+'× '+r.format+' (platform='+(r.platform||'')+'), дата '+r.date+(r.topic?(', тема: '+r.topic):''));
    confirmLines.push('• '+r.count+'× '+(FMT[r.format]||r.format)+' на '+r.date);
  });
  breakdownInline = lines.join(' // ');
  taskBreakdownText = lines.join('\n');
}

// Carry an editorial arc (one-line through-theme) for cohesion across chunks.
var planArc = context._planArc || '';

// Split resolvedTasks into THIS chunk (≤ CHUNK_MAX posts) and the remainder.
var planContTasks = [];
if (total > CHUNK_MAX && resolvedTasks.length) {
  var chunk = [], acc = 0, ri = 0;
  for (; ri < resolvedTasks.length; ri++) {
    var rt = resolvedTasks[ri];
    var rc = parseInt(rt.count,10)||1;
    if (acc > 0 && acc + rc > CHUNK_MAX) break; // keep whole date-buckets together
    chunk.push(rt); acc += rc;
  }
  if (!chunk.length) { chunk.push(resolvedTasks[0]); ri = 1; acc = parseInt(resolvedTasks[0].count,10)||1; }
  planContTasks = resolvedTasks.slice(ri);
  resolvedTasks = chunk;
  total = acc;
  lines = []; confirmLines = [];
  resolvedTasks.forEach(function(r){
    lines.push(r.count+'× '+r.format+' (platform='+(r.platform||'')+'), дата '+r.date+(r.topic?(', тема: '+r.topic):''));
    confirmLines.push('• '+r.count+'× '+(FMT[r.format]||r.format)+' на '+r.date);
  });
  breakdownInline = lines.join(' // ');
  taskBreakdownText = lines.join('\n');
}
var planContJson = JSON.stringify(planContTasks);
var planRemaining = planContTasks.reduce(function(a,r){ return a + (parseInt(r.count,10)||1); }, 0);

var routeIntent;
if(intent==='create') routeIntent = needsTheme ? 'propose_theme' : 'single_task';
else if(intent==='edit') routeIntent='edit_plan';
else if(intent==='save_rule') routeIntent='save_rule';
else if(intent==='new_plan') routeIntent='new_plan';
else routeIntent='dialog';

var agentInputText;
if(routeIntent==='propose_theme'){
  agentInputText='Користувач попросив створити контент, але НЕ вказав тему. Завдання: '+confirmLines.join(' ; ')+'. Зроби: 1) виклич list_posts щоб побачити що вже заплановано і не повторюватись; 2) виклич query_knowledge щоб взяти напрямки, болі ЦА і правила; 3) запропонуй РІВНО 3 конкретні теми (нумерований список, кожна — 1 рядок + чому зайде). НЕ створюй пости. В кінці попроси вибрати номер або написати свою тему.';
} else {
  agentInputText=(historyText?('Контекст діалогу:\n'+historyText+'\n\n'):'')+'Запит: '+originalMsg;
}
var agentInputJson=JSON.stringify(agentInputText).slice(1,-1);

var pl=(total===1)?'ня':((total<5)?'ня':'ь');
var confirmText = (Array.isArray(__ovr) && __ovr.length)
  ? ('⏳ Продовжую план: наступні '+total+' пост(ів)'+(planRemaining>0?(' (ще '+planRemaining+' після цього)'):' — фінальний шматок')+'…')
  : ('Зрозумів '+total+' завдан'+pl+':\n'+confirmLines.join('\n')+(planRemaining>0?('\n\n📅 Великий план: почну з '+total+' постів і сам продовжу рештою ('+planRemaining+') у фоні.'):'')+'\n\nГенерую контент — зачекай...');

var batchSize=7;
var batchCount=Math.max(1,Math.ceil(total/batchSize));
var firstCount=Math.min(total,batchSize);
var firstDate=resolvedTasks.length?resolvedTasks[0].date:todayISO;

var ukNote=' Пиши ВИКЛЮЧНО чистою українською, БЕЗ русизмів (напр. «пише» не «пишет», «що» не «что», «отримати» не «одержати»).';
var arcNote = planArc ? (' НАСКРІЗНА ЛІНІЯ МІСЯЦЯ (тримай єдиний стиль і тему в усіх постах): '+planArc) : '';
var progressText = batchCount>1
  ? ('Сьогодні: '+todayISO+'. Батч 1 із '+batchCount+'. Згенеруй перші '+firstCount+' обʼєктів за розкладом: '+breakdownInline+'.'+arcNote+ukNote)
  : ('Сьогодні: '+todayISO+'. Згенеруй РІВНО '+total+' обʼєктів СУВОРО за цим розкладом (формат/дата/кількість точно): '+breakdownInline+'. Не додавай зайвих постів. Дати точно як вказано, НЕ розкидай по різних днях.'+arcNote+ukNote);

return {
  _planContTasks: planContJson,
  _planRemaining: planRemaining,
  _planArc: planArc,
  _planTgChatId: context.tgChatId || context._planTgChatId || '',
  _planTgBotToken: context.tgBotToken || context._planTgBotToken || '',
  intent: routeIntent,
  needsTheme: needsTheme,
  intentParams: parsed,
  lastUserInput: originalMsg,
  resolvedTasks: JSON.stringify(resolvedTasks),
  taskBreakdownText: taskBreakdownText,
  confirmText: confirmText,
  agentInputJson: agentInputJson,
  singleFormat: resolvedTasks.length?resolvedTasks[0].format:'instagram_post',
  singlePlatform: resolvedTasks.length?resolvedTasks[0].platform:'instagram',
  singlePlatformLabel: 'Контент',
  singleTopic: themeFound || originalMsg,
  singleCount: total,
  singlePlatformsText: resolvedTasks.map(function(r){return r.platform;}).join(', ') || 'instagram',
  singleDurationDays: 7,
  singleConstraintsText: 'немає',
  batchTotalPosts: total,
  batchSize: batchSize,
  batchCount: batchCount,
  batchIndex: 0,
  batchCurrentCount: firstCount,
  batchDateFrom: firstDate,
  batchDoneTopics: 'ще немає',
  batchProgressText: progressText,
  stAllPosts: '[]',
  batchHasMore: false,
};

