var raw = context.stRulesRaw;
var isGood = typeof raw === 'string' && raw.trim().length > 50;
return {
  stRules: isGood ? raw.trim() : '',
  stRulesNeedFallback: !isGood,
};

var fallback = context.stRulesFallback || '';
if (fallback.trim().length > 50) {
  return { stRules: fallback.trim() };
}
return {};

var txt = context.dialogResponse || '';
return {
  webCallbackBody: JSON.stringify({
    text: txt,
    sessionId: context.webSessionId || ''
  })
};

return {
  webCallbackBody: JSON.stringify({
    text: 'Повний план на місяць — це багатоетапний процес з підтвердженням і батч-циклом.\nНапиши «план на місяць» в Telegram-бот.\nТут можу: пости, сторіз, карусель, reels, Threads, LinkedIn.',
    sessionId: context.webSessionId || ''
  })
};

var txt = context.agentResult || '';
return {
  webCallbackBody: JSON.stringify({
    text: txt,
    sessionId: context.webSessionId || ''
  })
};

// Early reply — підтвердження зрозумілих завдань + "генерую" (fire-and-forget)
var ackText = context.confirmText || '⏳ Прийнято в роботу. Генерую контент — зачекай...';
if (context.webCallbackUrl) {
  try {
    fetch(context.webCallbackUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text: ackText, sessionId: context.webSessionId || '' })
    });
  } catch(e) {}
}

// Створюємо порожні плейсхолдери в плані відразу → у плані видно «генерується текст» (fire-and-forget)
try {
  if (context.importUrl && context.resolvedTasks) {
    var phUrl = String(context.importUrl).replace('/api/posts/bulk-import', '/api/webhooks/chat-placeholders');
    var tasksArr = [];
    try { tasksArr = JSON.parse(context.resolvedTasks); } catch(e) {}
    if (Array.isArray(tasksArr) && tasksArr.length) {
      fetch(phUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ projectId: context.projectId, tasks: tasksArr })
      });
    }
  }
} catch(e) {}

// today may arrive as DD.MM.YY from dashboard — prefer ISO
var todayIso = context.todayISO || context.today || new Date().toISOString().slice(0,10);
if (!/^\d{4}-\d{2}-\d{2}$/.test(todayIso)) todayIso = new Date().toISOString().slice(0,10);
var d = new Date(todayIso);
d.setDate(d.getDate() - 30);
var dateFrom = d.toISOString().slice(0,10);
return { listPostsDateFrom: dateFrom };

var raw = context.topicHistoryRaw;
var posts = [];
if (Array.isArray(raw)) posts = raw;
else if (raw && Array.isArray(raw.posts)) posts = raw.posts;
else if (typeof raw === 'string') {
  try { var pj = JSON.parse(raw); posts = Array.isArray(pj) ? pj : (pj && Array.isArray(pj.posts) ? pj.posts : []); } catch(e) {}
}
if (!Array.isArray(posts)) posts = [];

var meta = posts.slice(-30).map(function(p) {
  var content = String(p.content || p.text || '').slice(0, 60).replace(/[\n\r]/g, ' ');
  return (p.post_date || p.date || '?') + ' [' + (p.platform || '?') + '/' + (p.post_type || 'post') + '] ' + content;
});

// single-line join — value is embedded into ST messagesTemplate JSON (no real newlines)
return {
  topicHistory: meta.length > 0 ? meta.join(' // ') : 'немає попередніх постів'
};

var msg = context.userMessage || context.lastUserInput || '';

// Extract a short title (first sentence or up to 60 chars)
var title = msg.replace(/^[\s\-:]+/, '');
var dot = title.indexOf('.');
var newline = title.indexOf('\n');
var end = Math.min(
  dot > 0 ? dot : 9999,
  newline > 0 ? newline : 9999,
  60
);
title = title.slice(0, end).trim();
if (!title) title = msg.slice(0, 50).trim();

// Full content with context
var content = 'ПРАВИЛО (додано ' + (context.today || new Date().toISOString().slice(0,10)) + '):\n' + msg;

var nlmBody = JSON.stringify({
  type: 'text',
  title: title,
  content: content
});

return {
  ruleTitle: title,
  ruleContent: content,
  ruleNlmBody: nlmBody,
};

var ok = context.nlmSaveResult && context.nlmSaveResult.ok !== false;
var text = ok
  ? '✅ Правило збережено в базу знань.\n\nБуде враховуватись при наступних генераціях.'
  : '⚠️ Правило збережено локально (база знань тимчасово недоступна).\nПовторимся автоматично пізніше.';
return {
  webCallbackBody: JSON.stringify({
    text: text,
    sessionId: context.webSessionId || ''
  })
};

var raw = context.stResult;

function salvageArray(s) {
  var out = [];
  var depth = 0, start = -1, inStr = false, esc = false;
  for (var i = 0; i < s.length; i++) {
    var ch = s[i];
    if (esc) { esc = false; continue; }
    if (ch === '\\') { esc = true; continue; }
